  /** A Hunter button in the bank's top-left corner that shows only the rumour's items. */
  private void addBankButton() {
    Widget universe = client.getWidget(InterfaceID.Bankmain.UNIVERSE);
    if (universe == null) return;
    Widget[] children = universe.getDynamicChildren();
    if (bankButton != null && children != null && Arrays.asList(children).contains(bankButton))
      return;
    // Ultimate Farming's button, itself Quest Helper's: 25px square at (408, 5), 19px icon inset by 3.
    bankButton = universe.createChild(-1, WidgetType.GRAPHIC);
    bankIcon = universe.createChild(-1, WidgetType.GRAPHIC);
    for (Widget w : new Widget[] {bankButton, bankIcon}) {
      int inset = w == bankIcon ? 3 : 0;
      w.setOriginalX(408 + inset);
      w.setOriginalY(5 + inset);
      w.setOriginalWidth(25 - 2 * inset);
      w.setOriginalHeight(25 - 2 * inset);
    }
    bankIcon.setSpriteId(SpriteID.SKILL_HUNTER);
    bankButton.setAction(0, "View Easy Rumours items");
    bankButton.setName("<col=ff9040>Easy Rumours</col>");
    bankButton.setHasListener(true);
    bankButton.setNoClickThrough(true);
    bankButton.setOnMouseOverListener(
        (JavaScriptCallback) ev -> bankButton.setSpriteId(SpriteID.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED));
    bankButton.setOnMouseLeaveListener((JavaScriptCallback) ev -> styleBankButton());
    bankButton.setOnOpListener(
        (JavaScriptCallback)
            ev -> {
              if (BANK_TAG.equals(bankTags.getActiveTag())) bankTags.closeBankTag();
              else bankTags.openBankTag(BANK_TAG, BankTagsService.OPTION_NO_LAYOUT);
              styleBankButton();
            });
    styleBankButton();
    bankButton.revalidate();
    bankIcon.revalidate();
  }

  /** The button stays pressed while the rumour items are shown. */
  private void styleBankButton() {
    if (bankButton == null) return;
    bankButton.setSpriteId(
        BANK_TAG.equals(bankTags.getActiveTag())
            ? SpriteID.UNKNOWN_BUTTON_SQUARE_SMALL_SELECTED
            : SpriteID.UNKNOWN_BUTTON_SQUARE_SMALL);
  }

  // ---------------------------------------------------------------- loadout

  /** Items that live in the huntsman's kit between rumours (wiki: the kit stores these). */
  private static final Set<String> KIT_ITEMS =
      new HashSet<>(Arrays.asList("Box trap", "Net trap", "Butterfly net", "Bird snare", "Noose wand", "Teasing stick"));

  /**
   * The rumour loadout: the solver's travel items, the huntsman's kit, and every hunting item of
   * the hunter's rumours (kept in the kit where it can hold them). Some players keep all of it on them.
   */
  /** Owned wiki-recommended extras, for the bank filter. */
  private Set<Integer> extraIds = new HashSet<>();

  private void loadout(View v, Hunter pool) {
    extraIds = new HashSet<>();
    List<KitItem> items = new ArrayList<>();
    List<String> missing = new ArrayList<>();
    Set<Integer> bankIds = new HashSet<>();
    int level = client.getRealSkillLevel(Skill.HUNTER);
    int slots = 0;
    boolean pouch = false;
    for (String g : loadout.groups) {
      Kit.Need need = new Kit.Need(g, false, false, "travel");
      KitItem item = travelItems(Collections.singletonList(need)).get(0);
      items.add(item);
      if (g.equals("Dramen or lunar staff")) item.note = "travel · wield it";
      else if (g.equals(Kit.HOUSE_TELEPORT)) {
        boolean cape = kit.owns(Kit.IDS.get("Construction cape"));
        boolean tabs = kit.owns(Kit.IDS.get("House teleport tablet"));
        item.note = cape ? "travel · construction cape" : tabs ? "travel · house tablets" : "travel · runes in your rune pouch";
        if (!cape && tabs) slots++;
        if (!cape && !tabs) pouch = true;
      } else slots++;
      if (!item.ok() && !item.where.startsWith("no") && !item.where.startsWith("not") && !item.where.startsWith("bank not")) {
        missing.add(item.name + " (" + item.where + ")");
        if (g.equals(Kit.HOUSE_TELEPORT))
          for (String h : new String[] {"House teleport tablet", "Construction cape", "Law rune", "Air rune", "Earth rune"})
            for (int id : Kit.IDS.get(h)) bankIds.add(id);
        else for (int id : Kit.IDS.getOrDefault(g, new int[0])) bankIds.add(id);
      }
    }
    // The huntsman's kit, carried, with every rumour's trap items in it.
    KitItem kitItem = new KitItem();
    kitItem.name = "Huntsman's kit";
    kitItem.icon = ItemID.HUNTSMANS_KIT;
    kitItem.have = count(InventoryID.INV, ItemID.HUNTSMANS_KIT);
    kitItem.want = 1;
    kitItem.note = "holds the traps";
    if (!kitItem.ok()) {
      kitItem.where = sum(bank, new int[] {ItemID.HUNTSMANS_KIT}) > 0 ? "in bank" : bank == null ? "bank not seen" : "not in bank";
      if (kitItem.where.equals("in bank")) {
        missing.add("Huntsman's kit (in bank)");
        bankIds.add(ItemID.HUNTSMANS_KIT);
      }
    }
    items.add(kitItem);
    slots++;
    Map<String, Kit.Need> hunting = new LinkedHashMap<>();
    Map<String, Integer> wants = new HashMap<>();
    for (Rumour r : Kit.POOLS.getOrDefault(pool, Collections.emptyList()))
      for (Kit.Need need : Kit.needs(r, level)) {
        if (need.optional || need.item.equals(Kit.TELEGRAB)) continue;
        hunting.putIfAbsent(need.item, need);
        wants.merge(need.item, want(need), Math::max);
      }
    for (Kit.Need need : hunting.values()) {
      KitItem item = new KitItem();
      item.name = need.item;
      item.icon = need.ids().length > 0 ? need.ids()[0] : -1;
      item.want = wants.get(need.item);
      int inKit = kitCarried() ? sum(huntsKit, need.ids()) : 0;
      item.have = have(need) + inKit;
      boolean storable = KIT_ITEMS.contains(need.item);
      item.note = storable ? (inKit > 0 ? "in your kit" : "store in your kit") : need.rune() ? "rune pouch" : "";
      if (!storable && !need.rune()) slots++;
      if (need.rune()) pouch = true;
      if (!item.ok()) {
        item.where = whereIs(need);
        if (item.where.equals("in bank") || item.where.startsWith("in kit (kit not")) {
          missing.add(need.item + (item.want > 1 ? " x" + (item.want - item.have) : "") + " (" + item.where + (storable ? ", then into the kit" : "") + ")");
          for (int id : need.ids()) bankIds.add(id);
        }
      }
      items.add(item);
    }
    if (pouch) slots++;
    // Wiki-recommended extras, only those owned; optional, so they never hold the guide.
    Set<Trap> traps = new HashSet<>();
    for (Rumour r : Kit.POOLS.getOrDefault(pool, Collections.emptyList())) traps.add(r.creature.trap);
    int extraSlots = 0;
    for (Kit.Extra x : Kit.EXTRAS) {
      if (!x.traps.isEmpty() && Collections.disjoint(x.traps, traps)) continue;
      if (!kit.owns(x.ids)) continue;
      // Only one bonecrusher.
      if (x.name.equals("Bonecrusher") && kit.owns(new int[] {ItemID.BONECRUSHER_NECKLACE})) continue;
      KitItem item = new KitItem();
      item.name = x.name;
      item.icon = x.ids[0];
      item.want = 1;
      item.have = carried(x.ids) + (kitCarried() ? sum(huntsKit, x.ids) : 0);
      item.optional = true;
      item.note = "recommended: " + x.why;
      if (!item.ok()) item.where = sum(bank, x.ids) > 0 ? "in bank" : "in kit (kit not carried)";
      if (!x.worn) extraSlots++;
      items.add(item);
      extraIds.addAll(Arrays.stream(x.ids).boxed().collect(java.util.stream.Collectors.toList()));
    }
    List<String> lines = new ArrayList<>();
    for (Map.Entry<Rumour, Travel.Plan> e : loadout.plans.entrySet())
      lines.add(e.getKey().name + ": " + (e.getValue().route == Travel.WALK ? "walk from the guild" : e.getValue().route.text));
    if (loadout.back != null) lines.add("Back to the guild: " + loadout.back.text);
    v.loadout = items;
    v.loadoutLines = lines;
    v.loadoutSlots =
        "About " + slots + " inventory slots" + (pouch ? ", runes in your rune pouch" : "")
            + (extraSlots > 0 ? ", +" + extraSlots + " for the recommended extras" : "") + ".";
    v.loadoutMissing = missing;
    v.loadoutBank = bankIds;
  }

  /** What a need gives now, counting items stored in a carried huntsman's kit. */
  private int available(Kit.Need need) {
    return have(need) + (kitCarried() && !need.rune() ? sum(huntsKit, need.ids()) : 0);
  }

  // ---------------------------------------------------------------- kit

  private int sum(Map<Integer, Integer> items, int[] ids) {
    if (items == null) return 0;
    int n = 0;
    for (int id : ids) n += items.getOrDefault(id, 0);
    return n;
  }

  private int carried(int[] ids) {
    return count(InventoryID.INV, ids) + count(InventoryID.WORN, ids);
  }

  /** Items stored in the kit can't be used, so they only count once taken out. */
  private boolean kitCarried() {
    return count(InventoryID.INV, ItemID.HUNTSMANS_KIT) > 0;
  }

  /**
   * How many of a need are usable now: carried or worn; runes also in the rune pouch; an air staff
   * worn covers air runes; the spell is 1 when castable.
   */
  private int have(Kit.Need need) {
    if (need.item.equals(Kit.HOUSE_TELEPORT)) return houseTeleport(true) ? 1 : 0;
    if (need.item.equals(Kit.TELEGRAB))
      return client.getRealSkillLevel(Skill.MAGIC) >= 33
              && client.getVarbitValue(VarbitID.SPELLBOOK) == 0
          ? 1
          : 0;
    int n = carried(need.ids());
    if (need.rune()) n += sum(pouchRunes(), need.ids());
    if (need.item.equals("Air rune") && count(InventoryID.WORN, Kit.IDS.get("Air staff")) > 0)
      n = Math.max(n, 1);
    return n;
  }

  private static final int[][] POUCH_SLOTS = {
    {VarbitID.RUNE_POUCH_TYPE_1, VarbitID.RUNE_POUCH_QUANTITY_1},
    {VarbitID.RUNE_POUCH_TYPE_2, VarbitID.RUNE_POUCH_QUANTITY_2},
    {VarbitID.RUNE_POUCH_TYPE_3, VarbitID.RUNE_POUCH_QUANTITY_3},
    {VarbitID.RUNE_POUCH_TYPE_4, VarbitID.RUNE_POUCH_QUANTITY_4},
    {VarbitID.RUNE_POUCH_TYPE_5, VarbitID.RUNE_POUCH_QUANTITY_5},
    {VarbitID.RUNE_POUCH_TYPE_6, VarbitID.RUNE_POUCH_QUANTITY_6}
  };

  /** Rune item IDs and amounts inside the rune pouch, read from its varbits (as Ultimate Farming). */
  private Map<Integer, Integer> pouchRunes() {
    Map<Integer, Integer> runes = new HashMap<>();
    EnumComposition types = client.getEnum(EnumID.RUNEPOUCH_RUNE);
    for (int[] slot : POUCH_SLOTS) {
      int type = client.getVarbitValue(slot[0]), amount = client.getVarbitValue(slot[1]);
      if (type <= 0 || amount <= 0 || types == null) continue;
      int id = types.getIntValue(type);
      if (id > 0) runes.merge(id, amount, Integer::sum);
    }
    return runes;
  }

  private int want(Kit.Need need) {
    return need.perTrap ? Kit.trapCount(client.getRealSkillLevel(Skill.HUNTER)) : 1;
  }

  /** Where a not-carried item is: "in kit", "in bank", "not in bank" or "bank not seen". */
  private String whereIs(Kit.Need need) {
    if (need.item.equals(Kit.HOUSE_TELEPORT))
      return houseTeleport(false) ? "in bank (tablets, cape or runes)" : "no tablets, cape or runes seen";
    if (need.item.equals(Kit.TELEGRAB))
      return client.getRealSkillLevel(Skill.MAGIC) < 33 ? "needs 33 Magic" : "standard spellbook";
    int[] ids = need.ids();
    if (sum(huntsKit, ids) > 0) return kitCarried() ? "in kit" : "in kit (kit not carried)";
    if (sum(bank, ids) > 0) return "in bank";
    return bank == null ? "bank not seen" : "not in bank";
  }

  /** Required items for this rumour not carried, with where they are. */
  private List<String> missing(Rumour r) {
    List<String> out = new ArrayList<>();
    // Items in a carried huntsman's kit count: they're taken out at the area.
    for (Kit.Need need : allNeeds())
      if (!need.optional && available(need) == 0)
        out.add(need.item + " (" + whereIs(need) + ")");
    return out;
  }

  private List<KitRow> kitRows(Hunter h) {
    List<KitRow> rows = new ArrayList<>();
    List<Rumour> pool = new ArrayList<>(Kit.POOLS.getOrDefault(h, Collections.emptyList()));
    if (rumour != Rumour.NONE && !pool.contains(rumour)) pool.add(0, rumour);
    int level = client.getRealSkillLevel(Skill.HUNTER);
    for (Rumour r : pool) {
      KitRow row = new KitRow(r, r == rumour);
      List<Kit.Need> needs = Kit.needs(r, level);
      for (Kit.Need need : needs) {
        KitItem item = new KitItem();
        item.name = need.item;
        item.note = need.note;
        item.icon = need.ids().length > 0 ? need.ids()[0] : -1;
        item.have = have(need);
        item.want = want(need);
        item.optional = need.optional;
        if (!item.ok()) item.where = whereIs(need);
        if (item.have == 0 && !need.optional) row.ready = false;
        row.items.add(item);
      }
      rows.add(row);
    }
    return rows;
  }

  private static final int[] BANKERS = {
    net.runelite.api.gameval.NpcID.HG_BANK_BUFFALO, net.runelite.api.gameval.NpcID.HG_BANKER_DWARF
  };

  /** Bank first: take the item out of the huntsman's kit, or withdraw it at the burrows bank. */
  private void getItems(View v) {
    // This rumour's own items first (unless skipped), then the loadout.
    Set<Integer> ids = new HashSet<>();
    if (!skipItems)
      for (Kit.Need need : allNeeds())
        if (!need.optional && available(need) == 0) {
          for (int id : need.ids()) ids.add(id);
          if (need.item.equals(Kit.HOUSE_TELEPORT))
            for (String g : new String[] {"House teleport tablet", "Construction cape", "Law rune", "Air rune", "Earth rune"})
              for (int id : Kit.IDS.get(g)) ids.add(id);
        }
    if (!ids.isEmpty()) v.instruction = "Get " + String.join(", ", v.missing);
    else {
      ids.addAll(v.loadoutBank);
      v.instruction = "Withdraw your rumour loadout: " + String.join(", ", v.loadoutMissing);
    }
    if (bank == null) v.instruction += " · open the bank once so I can check it";
    v.bankItems = ids;
    v.npcs =
        npcs(
            n -> {
              for (int b : BANKERS) if (n.getId() == b) return true;
              return false;
            },
            30);
  }
  int pity() {
    return rumour == Rumour.NONE ? 0 : rumour.creature.trap.pityFor(outfitPieces());
  }

  private void completed(Rumour done) {
    sessionCompletions++;
    if (doneStart > 0) {
      long now = System.currentTimeMillis();
      lastRumourMillis = now - doneStart;
      Record r = new Record();
      r.rumour = done.name();
      r.catches = doneCatches;
      r.pity = donePity;
      r.toPart = donePartAt > doneStart ? donePartAt - doneStart : 0;
      r.total = now - doneStart;
      r.at = now;
      synchronized (records) {
        records.add(r);
        configManager.setRSProfileConfiguration(RumoursConfig.GROUP, "records", gson.toJson(records));
      }
      event("recorded " + done.name + " " + r.catches + "/" + r.pity + " in " + r.total / 1000 + "s");
    }
    configManager.setRSProfileConfiguration(
        RumoursConfig.GROUP, "completions", String.valueOf(totalCompletions() + 1));
    event("handed in: " + done.name + " #" + sessionCompletions);
    partFound = false;
    // A new rumour may already have been given in the same conversation; keep it.
    if (rumour == done) {
      rumour = Rumour.NONE;
      catches = 0;
      rumourStart = 0;
      save();
    }
  }

  /** Travel guidance: the stairs, a walk, or the teleport item/spell then the quetzal map icon. */
  private void travel(View v, Travel.Route route, WorldPoint here, boolean toGuild, String where) {
    boolean burrows = Travel.inBurrows(here);
    boolean inHouse = client.getTopLevelWorldView().isInstance();
    v.route = route.text;
    if (route.house && !teleported) {
      String obj = route.pohObject;
      String name =
          obj.equals("fairy") ? "fairy ring" : obj.equals("spirit") ? "spirit tree" : obj.equals("nexus") ? "portal nexus" : "jewellery box";
      if (inHouse) {
        leg = "2/3 in house";
        v.instruction = "Use the " + name + " → " + route.pohChoice;
        int[] staff = Kit.IDS.get("Dramen or lunar staff");
        if (route.needs.contains("Dramen or lunar staff")
            && count(InventoryID.WORN, staff) == 0
            && count(InventoryID.INV, staff) > 0) {
          Set<Integer> ids = new HashSet<>();
          for (int id : staff) ids.add(id);
          v.items = ids;
          v.instruction = "Wield your staff, then use the " + name + " → " + route.pohChoice;
          return;
        }
        // UNVERIFIED house object names: matched by a word in the name ("fairy", "spirit",
        // "nexus", "jewellery").
        v.objects = objects(40, n -> n.toLowerCase(Locale.ROOT).contains(obj));
        return;
      }
      leg = "1/3 house teleport";
      v.instruction = "Teleport to your house, then the " + name + " → " + route.pohChoice;
      int[] tab = Kit.IDS.get("House teleport tablet"), cape = Kit.IDS.get("Construction cape");
      Set<Integer> ids = new HashSet<>();
      if (carries(tab)) for (int id : tab) ids.add(id);
      else if (carries(cape)) for (int id : cape) ids.add(id);
      if (!ids.isEmpty()) v.items = ids;
      else v.spell = "Teleport to House";
      return;
    }
    leg = route == Travel.WALK ? "walk" : teleported ? "after teleport" : "1 teleport";
    if (route.house) {
      v.instruction = "Walk to " + (toGuild ? "the Hunter Guild" : where);
      if (toGuild && Travel.nearGuild(here)) {
        v.instruction = "Take the stairs down to the burrows";
        v.objects = stairs("climb-down", 40);
      }
      return;
    }
    if (route == Travel.WALK) {
      if (toGuild && Travel.nearGuild(here)) {
        v.instruction = where + ": take the stairs down";
        v.objects = stairs("climb-down", 40);
      } else if (!toGuild && burrows) {
        v.instruction = "Climb the stairs up, then walk to " + where;
        v.objects = stairs("climb-up", 20);
      } else if (toGuild) {
        v.instruction = where + ": walk to the Hunter Guild";
      } else {
        v.instruction = "Walk to " + where + (v.distance >= 0 ? " (" + v.distance + " tiles)" : "");
      }
      return;
    }
    v.instruction = route.text + (toGuild ? "" : " (" + where + ")");
    v.quetzalSite = route.quetzalSite;
    if (teleported) {
      // The item or spell is used; only the second leg or the walk is left.
      if (route.multiLeg && route.quetzalSite != null) v.instruction = "Take the quetzal to " + (toGuild ? "Hunter Guild" : where);
      else v.instruction = "Walk to " + (toGuild ? "the Hunter Guild" : where);
      return;
    }
    if (route.items.length > 0) {
      Set<Integer> ids = new HashSet<>();
      for (int id : route.items) ids.add(id);
      v.items = ids;
    }
    v.spell = route.spell;
    if (route.object != null) {
      // Fairy rings: wield the staff first, then the ring itself. UNVERIFIED object name.
      int[] staff = Kit.IDS.get("Dramen or lunar staff");
      if (route.needs.contains("Dramen or lunar staff")
          && count(InventoryID.WORN, staff) == 0
          && count(InventoryID.INV, staff) > 0) {
        Set<Integer> ids = new HashSet<>();
        for (int id : staff) ids.add(id);
        v.items = ids;
        v.instruction = "Wield your staff, then " + route.text;
      } else {
        String name = route.object.toLowerCase(Locale.ROOT);
        v.objects = objects(25, o -> name.equals(o.toLowerCase(Locale.ROOT)));
      }
    }
  }

  /** Objects within range whose name matches. */
  private List<TileObject> objects(int range, java.util.function.Predicate<String> name) {
    List<TileObject> found = new ArrayList<>();
    for (TileObject o : nearbyObjects(range)) {
      ObjectComposition c = composition(o);
      if (c != null && c.getName() != null && name.test(c.getName())) found.add(o);
    }
    return found;
  }

  /** Kit view of the route's items. */
  private List<KitItem> travelItems(List<Kit.Need> needs) {
    List<KitItem> out = new ArrayList<>();
    for (Kit.Need need : needs) {
      KitItem item = new KitItem();
      item.name = need.item;
      item.note = "travel";
      item.icon =
          need.ids().length > 0
              ? need.ids()[0]
              : need.item.equals(Kit.HOUSE_TELEPORT) ? ItemID.POH_TABLET_TELEPORTTOHOUSE : -1;
      item.have = have(need);
      item.want = 1;
      if (!item.ok()) item.where = whereIs(need);
      out.add(item);
    }
    return out;
  }

  /** At the area: the creature, traps ready to check, and the trap item to lay. */
  private void hunt(View v, WorldPoint here) {
    // Items stored in the huntsman's kit can't be used: take them out first.
    for (Kit.Need need : Kit.needs(rumour, client.getRealSkillLevel(Skill.HUNTER)))
      if (!need.optional && have(need) == 0 && kitCarried() && sum(huntsKit, need.ids()) > 0) {
        v.instruction = "Take " + need.item + (need.perTrap ? "s" : "") + " out of your huntsman's kit";
        v.items = Collections.singleton(ItemID.HUNTSMANS_KIT);
        return;
      }
    if (rumour == Rumour.WYRMSCRAIG_GOAT) {
      goatHunt(v);
      return;
    }
    if (rumour.creature.trap == Trap.FALCONRY) {
      falconry(v);
      return;
    }
    Creature creature = rumour.creature;
    Trap trap = creature.trap;
    v.instruction = "Catch " + rumour.name + " (" + trap.name + ")";
    v.npcs = npcs(n -> creature.isNpc(n.getId()), 20);
    // UNVERIFIED: caught traps offer "Check"; unset trap spots offer "Set-trap".
    v.objects = objects(a -> a.equals("check"), 15);
    if (!trap.laidFromInventory && trap != Trap.BUTTERFLY && trap != Trap.FALCONRY)
      v.nextObjects = objects(a -> a.equals("set-trap"), 8);
    Set<Integer> next = new HashSet<>();
    if (trap.laidFromInventory) for (int id : trap.items) next.add(id);
    v.nextItems = next;
    // A butterfly net must be wielded before the creature can be caught.
    List<String> lacking = missing(rumour);
    if (!lacking.isEmpty()) v.instruction = "Missing " + String.join(", ", lacking);
    else if (trap == Trap.BUTTERFLY && count(InventoryID.WORN, trap.items) == 0) {
      Set<Integer> net = new HashSet<>();
      for (int id : trap.items) net.add(id);
      v.items = net;
      v.instruction = "Wield your butterfly net";
    }
  }

  // ---------------------------------------------------------------- rare part on the floor

  /** Tiles where a rare part (any rumour's) lies, from ground item events. */
  private final Map<Tile, Integer> partsOnGround = new HashMap<>();

  private static final Set<Integer> RARE_PARTS = new HashSet<>();

  static {
    for (Rumour r : Rumour.values()) if (r != Rumour.NONE) RARE_PARTS.add(r.rarePart);
  }

  @Subscribe
  public void onItemSpawned(ItemSpawned e) {
    if (RARE_PARTS.contains(e.getItem().getId())) {
      partsOnGround.put(e.getTile(), e.getItem().getId());
      if (rumour != Rumour.NONE && e.getItem().getId() == rumour.rarePart) event("rare part on the floor");
    }
  }

  @Subscribe
  public void onItemDespawned(ItemDespawned e) {
    if (RARE_PARTS.contains(e.getItem().getId())) partsOnGround.remove(e.getTile());
  }

  /** The nearest tile (within 15) with this rumour's rare part on it, or null. */
  private Tile groundPartTile() {
    if (rumour == Rumour.NONE) return null;
    Player player = client.getLocalPlayer();
    Tile best = null;
    int bestDistance = 16;
    for (Map.Entry<Tile, Integer> e : partsOnGround.entrySet()) {
      if (e.getValue() != rumour.rarePart) continue;
      int d = e.getKey().getWorldLocation().distanceTo(player.getWorldLocation());
      if (d < bestDistance) {
        best = e.getKey();
        bestDistance = d;
      }
    }
    return best;
  }

  // ---------------------------------------------------------------- falconry

  /** Matthias, with and without a falcon on his arm (gameval NpcID). */
  private static final int[] FALCONERS = {
    net.runelite.api.gameval.NpcID.HUNTING_NPC_FALCONER, net.runelite.api.gameval.NpcID.HUNTING_NPC_FALCONER_NOBIRD
  };
  /** A falcon sitting on a caught kebbit, waiting to be retrieved. */
  private static final int[] FALCON_ON_KEBBIT = {
    net.runelite.api.gameval.NpcID.HUNTING_FALCON_ONSPEEDY,
    net.runelite.api.gameval.NpcID.HUNTING_FALCON_ONSPEEDY2,
    net.runelite.api.gameval.NpcID.HUNTING_FALCON_ONSILENT
  };

  /**
   * Falconry (Piscatoris falconry area; Teco gives none, other hunters do), one step at a time:
   * over the fence stile, a falcon from Matthias, then the kebbits; a falcon sitting on a catch is
   * retrieved first. UNVERIFIED: the stile is found by its name ("Stile") and "Climb-over"; you're
   * taken to be inside the fence when you're nearer the hunting spots than the stile is.
   */
  private void falconry(View v) {
    Creature creature = rumour.creature;
    boolean falcon = count(InventoryID.WORN, ItemID.FALCON_ON_GLOVES) > 0;
    boolean glove = falcon || count(InventoryID.WORN, ItemID.FALCON_GLOVES) > 0;
    List<NPC> waiting = npcs(n -> Arrays.stream(FALCON_ON_KEBBIT).anyMatch(id -> id == n.getId()), 20);
    if (glove && !waiting.isEmpty()) {
      v.instruction = "Retrieve your falcon";
      v.npcs = waiting;
      return;
    }
    if (falcon) {
      v.instruction = "Send your falcon after a " + rumour.name;
      v.npcs = npcs(n -> creature.isNpc(n.getId()), 20);
      return;
    }
    if (glove) {
      v.instruction = "Wait for your falcon to come back";
      return;
    }
    List<TileObject> stiles =
        objects(20, name -> name.equalsIgnoreCase("stile")).stream()
            .filter(o -> hasAction(composition(o), a -> a.equals("climb-over")))
            .collect(java.util.stream.Collectors.toList());
    List<NPC> falconers = npcs(n -> Arrays.stream(FALCONERS).anyMatch(id -> id == n.getId()), 25);
    WorldPoint here = client.getLocalPlayer().getWorldLocation();
    Travel.Plan plan = Travel.plan(rumour, here, kit);
    boolean inside =
        stiles.isEmpty()
            || plan != null && plan.distance(here) < plan.distance(stiles.get(0).getWorldLocation());
    if (!inside) {
      v.instruction = "Climb over the stile into the falconry area";
      v.objects = stiles;
      v.nextNpcs = falconers;
      return;
    }
    v.instruction = "Get a falcon from Matthias";
    v.npcs = falconers;
  }

  private List<NPC> npcs(java.util.function.Predicate<NPC> match, int range) {
    Player player = client.getLocalPlayer();
    List<NPC> found = new ArrayList<>();
    for (NPC n : client.getTopLevelWorldView().npcs())
      if (n != null
          && match.test(n)
          && n.getWorldLocation().distanceTo(player.getWorldLocation()) <= range) found.add(n);
    return found;
  }

  /** Stairs (any object named "...stair...") with this action, within range. UNVERIFIED names. */
  private List<TileObject> stairs(String action, int range) {
    List<TileObject> found = new ArrayList<>();
    for (TileObject o : nearbyObjects(range)) {
      ObjectComposition c = composition(o);
      if (c == null || c.getName() == null) continue;
      String name = c.getName().toLowerCase(Locale.ROOT);
      if ((name.contains("stair") || name.contains("steps")) && hasAction(c, a -> a.equals(action)))
        found.add(o);
    }
    return found;
  }

  private List<TileObject> objects(java.util.function.Predicate<String> action, int range) {
    List<TileObject> found = new ArrayList<>();
    for (TileObject o : nearbyObjects(range)) {
      ObjectComposition c = composition(o);
      if (c != null && hasAction(c, action)) found.add(o);
    }
    return found;
  }

  private ObjectComposition composition(TileObject o) {
    ObjectComposition c = client.getObjectDefinition(o.getId());
    if (c != null && c.getImpostorIds() != null) c = c.getImpostor();
    return c;
  }

  private static boolean hasAction(ObjectComposition c, java.util.function.Predicate<String> match) {
    String[] actions = c.getActions();
    if (actions == null) return false;
    for (String a : actions) if (a != null && match.test(a.toLowerCase(Locale.ROOT))) return true;
    return false;
  }

  private List<TileObject> nearbyObjects(int range) {
    List<TileObject> found = new ArrayList<>();
    Player player = client.getLocalPlayer();
    if (player == null) return found;
    LocalPoint local = player.getLocalLocation();
    WorldView world = client.getTopLevelWorldView();
    Tile[][] plane = world.getScene().getTiles()[world.getPlane()];
    int sx = local.getSceneX(), sy = local.getSceneY();
    for (int x = Math.max(0, sx - range); x <= Math.min(plane.length - 1, sx + range); x++)
      for (int y = Math.max(0, sy - range); y <= Math.min(plane[x].length - 1, sy + range); y++) {
        Tile tile = plane[x][y];
        if (tile == null) continue;
        for (GameObject o : tile.getGameObjects()) if (o != null) found.add(o);
        if (tile.getGroundObject() != null) found.add(tile.getGroundObject());
        if (tile.getWallObject() != null) found.add(tile.getWallObject());
        if (tile.getDecorativeObject() != null) found.add(tile.getDecorativeObject());
      }
    return found;
  }

  /** Whether the player has this item selected ("Use"), ready to click its target. */
  boolean selectedItem(Set<Integer> ids) {
    if (!client.isWidgetSelected()) return false;
    Widget selected = client.getSelectedWidget();
    return selected != null && ids.contains(selected.getItemId());
  }

  // ---------------------------------------------------------------- debug

  private void event(String text) {
    String line = text.length() > 44 ? text.substring(0, 44) + "…" : text;
    if (line.equals(events.peekFirst())) return;
    events.addFirst(line);
    while (events.size() > 4) events.removeLast();
  }

  /** What the plugin currently believes, for the debug box. Called on the client thread. */
  List<String> debugLines() {
    View v = view;
    List<String> lines = new ArrayList<>();
    lines.add("hunter " + v.hunter + " · rumour " + v.rumour.name);
    if (v.rumour != Rumour.NONE) {
      Creature c = v.rumour.creature;
      lines.add("creature " + c.name() + " npc " + Arrays.toString(c.npcIds) + " xp " + Arrays.toString(c.xpDrops.length > 4 ? Arrays.copyOf(c.xpDrops, 2) : c.xpDrops));
      lines.add("catches " + v.catches + "/" + v.pity + " · outfit " + outfitPieces() + " · part " + v.hasPart);
    }
    lines.add("step " + v.step.label + (teleported ? " (teleported)" : "") + " · area " + (v.area.isEmpty() ? "-" : v.area) + " · dist " + v.distance);
    lines.add("route " + lastRoute);
    lines.add(
        "leg " + leg + " · in house " + client.getTopLevelWorldView().isInstance()
            + " · teleported " + teleported + (lockedRoute != null ? " · locked" : ""));
    lines.add("leg reason: " + legReason);
    Player player = client.getLocalPlayer();
    if (player != null) {
      WorldPoint p = player.getWorldLocation();
      lines.add("you " + p.getX() + "," + p.getY() + "," + p.getPlane() + " burrows " + Travel.inBurrows(p) + " guild " + p.distanceTo(Travel.GUILD));
    }
    lines.add("lit: npcs " + v.npcs.size() + " objs " + v.objects.size() + "/" + v.nextObjects.size() + " items " + v.items + v.nextItems + (v.spell != null ? " spell" : ""));
    lines.add("dialog: " + (lastDialog.length() > 60 ? lastDialog.substring(0, 60) + "…" : lastDialog));
    lines.add("last hunter xp: " + lastXp);
    if (v.goatInPit >= 0) {
      lines.add("goat step " + goatStep + " · pit " + goatPitDebug);
      for (String g : goatVerdicts) lines.add("  " + g);
    }
    if (v.goatInPit >= 0)
      lines.add(
          "goats: in pit " + v.goatInPit + "/" + v.goatCapacity + " cleared " + v.goatCleared
              + " · varbits inpit " + client.getVarbitValue(VarbitID.GOAT_PIT_INPIT)
              + " state " + client.getVarbitValue(VarbitID.GOAT_PIT_STATE)
              + " spikes " + client.getVarbitValue(VarbitID.GOAT_PIT_SPIKES)
              + " varp " + client.getVarpValue(VarPlayerID.GOAT_PIT_VARP));
    lines.add(
        "huntsman's kit " + (huntsKit == null ? "never seen" : huntsKit.size() + " types")
            + " · carried " + kitCarried() + " · bank " + (bank == null ? "never seen" : bank.size() + " types"));
    if (!v.missing.isEmpty()) lines.add("missing: " + String.join(", ", v.missing));
    lines.add("quetzal varbits HG " + client.getVarbitValue(VarbitID.QUETZAL_HUNTERGUILD) + " TT " + client.getVarbitValue(VarbitID.QUETZAL_TALTEKLAN) + " AV " + client.getVarbitValue(VarbitID.QUETZAL_AUBURNVALLEY) + " book " + client.getVarbitValue(VarbitID.SPELLBOOK));
    // While a quetzal map is open, list its icons so the map highlight's wording can be checked.
    for (int id : new int[] {InterfaceID.QuetzalwhistleMenu.ICONS, InterfaceID.QuetzalMenu.ICONS}) {
      Widget icons = client.getWidget(id);
      Widget[] children = icons == null || icons.isHidden() ? null : icons.getDynamicChildren();
      if (children == null) continue;
      List<String> names = new ArrayList<>();
      for (Widget w : children)
        if (w != null && w.getName() != null && !w.getName().isEmpty())
          names.add(Text.removeTags(w.getName()));
      lines.add("quetzal icons: " + String.join(", ", names));
    }
    // Objects with actions right next to the player, to check stairs/trap wording.
    if (player != null) {
      Set<String> near = new LinkedHashSet<>();
      for (TileObject o : nearbyObjects(3)) {
        ObjectComposition c = composition(o);
        if (c == null || c.getName() == null || c.getName().equals("null")) continue;
        List<String> acts = new ArrayList<>();
        for (String a : c.getActions()) if (a != null) acts.add(a);
        if (!acts.isEmpty()) near.add(c.getName() + "[" + String.join("/", acts) + "]");
      }
      if (!near.isEmpty()) lines.add("near: " + String.join(", ", near));
    }
    for (String e : events) lines.add("> " + e);
    return lines;
  }
}

package com.yonwi.rumours;

import java.awt.*;
import java.util.List;
import java.util.Map;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.NPC;
import net.runelite.api.Perspective;
import net.runelite.api.TileObject;
import net.runelite.api.coords.LocalPoint;
import net.runelite.client.ui.FontManager;
import net.runelite.client.ui.overlay.*;

/**
 * In the world: the hunter, stairs, creatures and caught traps in blue; trap spots in orange;
 * the goat pit's goats, numbers, stand tile, ring and field outline (styled by the Goats
 * settings); and the rare-part rainbow.
 */
final class RumoursSceneOverlay extends Overlay {
  /** One full trip round the colour wheel; slow, so it never strobes. */
  private static final long RAINBOW_PERIOD_MS = 4000;

  private final RumoursPlugin plugin;
  private final RumoursConfig config;
  private final Client client;

  @Inject
  RumoursSceneOverlay(RumoursPlugin plugin, RumoursConfig config, Client client) {
    this.plugin = plugin;
    this.config = config;
    this.client = client;
    setPosition(OverlayPosition.DYNAMIC);
    setLayer(OverlayLayer.ABOVE_SCENE);
  }

  @Override
  public Dimension render(Graphics2D g) {
    if (client.getGameState() != GameState.LOGGED_IN) return null;
    RumoursPlugin.View v = plugin.view();
    if (v.rainbow) {
      float hue = (System.currentTimeMillis() % RAINBOW_PERIOD_MS) / (float) RAINBOW_PERIOD_MS;
      Color c = Color.getHSBColor(hue, 0.9f, 1f);
      // 20% opacity.
      g.setColor(new Color(c.getRed(), c.getGreen(), c.getBlue(), 51));
      g.fillRect(0, 0, client.getCanvasWidth(), client.getCanvasHeight());
    }
    if (!config.highlight()) return null;
    boolean goats = v.goatInPit >= 0;
    if (goats && !v.goatArea.isEmpty()) outline(g, v.goatArea, config.goatAreaColour());
    for (LocalPoint lp : v.standRing) tile(g, lp, config.goatRingColour(), false);
    for (TileObject o : v.nextObjects) draw(g, o, RumoursWidgetOverlay.NEXT);
    for (TileObject o : v.objects) draw(g, o, RumoursWidgetOverlay.TARGET);
    for (NPC npc : v.npcs)
      if (goats) goat(g, npc, config.goatTargetColour());
      else RumoursWidgetOverlay.mark(g, npc.getConvexHull(), RumoursWidgetOverlay.TARGET);
    for (NPC npc : v.nextNpcs) RumoursWidgetOverlay.mark(g, npc.getConvexHull(), RumoursWidgetOverlay.NEXT);
    if (v.groundPart != null) {
      Polygon tile = Perspective.getCanvasTilePoly(client, v.groundPart);
      if (tile != null) {
        RumoursWidgetOverlay.mark(g, tile, Style.GOLD);
        g.setStroke(new BasicStroke(4));
        g.draw(tile);
      }
    }
    for (NPC npc : v.grabbed) goat(g, npc, config.grabbedColour());
    if (config.goatNumbers() && !v.npcLabels.isEmpty()) {
      g.setFont(FontManager.getRunescapeBoldFont().deriveFont((float) config.goatNumberSize()));
      for (Map.Entry<NPC, Integer> e : v.npcLabels.entrySet()) {
        NPC npc = e.getKey();
        String text = String.valueOf(e.getValue());
        net.runelite.api.Point at = npc.getCanvasTextLocation(g, text, npc.getLogicalHeight() + 40);
        if (at != null) OverlayUtil.renderTextLocation(g, at, text, config.goatNumberColour());
      }
    }
    if (v.standTile != null) tile(g, v.standTile, config.goatStandColour(), true);
    return null;
  }

  /** A goat in the chosen style: filled hull, outline only, or its tile. */
  private void goat(Graphics2D g, NPC npc, Color color) {
    switch (config.goatStyle()) {
      case OUTLINE:
        Shape hull = npc.getConvexHull();
        if (hull == null) return;
        g.setColor(color);
        g.setStroke(new BasicStroke(2));
        g.draw(hull);
        break;
      case TILE:
        if (npc.getLocalLocation() != null) tile(g, npc.getLocalLocation(), color, true);
        break;
      case HULL:
      default:
        RumoursWidgetOverlay.mark(g, npc.getConvexHull(), color);
    }
  }

  private void tile(Graphics2D g, LocalPoint lp, Color color, boolean filled) {
    Polygon poly = Perspective.getCanvasTilePoly(client, lp);
    if (poly == null) return;
    if (filled) RumoursWidgetOverlay.mark(g, poly, color);
    else {
      g.setColor(color);
      g.setStroke(new BasicStroke(1.5f));
      g.draw(poly);
    }
  }

  private void outline(Graphics2D g, List<LocalPoint> points, Color color) {
    Polygon outline = new Polygon();
    for (LocalPoint lp : points) {
      net.runelite.api.Point p =
          Perspective.localToCanvas(client, lp, client.getTopLevelWorldView().getPlane());
      if (p == null) return;
      outline.addPoint(p.getX(), p.getY());
    }
    g.setColor(color);
    g.setStroke(new BasicStroke(2));
    g.draw(outline);
  }

  private static void draw(Graphics2D g, TileObject object, Color color) {
    RumoursWidgetOverlay.mark(
        g, object.getClickbox() != null ? object.getClickbox() : object.getCanvasTilePoly(), color);
  }
}

package com.yonwi.rumours;

import java.awt.*;
import java.util.*;
import javax.inject.Inject;
import net.runelite.api.Client;
import net.runelite.api.GameState;
import net.runelite.api.Item;
import net.runelite.api.ItemContainer;
import net.runelite.api.gameval.InterfaceID;
import net.runelite.api.gameval.InventoryID;
import net.runelite.api.gameval.VarClientID;
import net.runelite.api.widgets.Widget;
import net.runelite.client.ui.overlay.*;
import net.runelite.client.util.Text;

/**
 * Leads the player through the interface: the side tab to open, then the item, worn item or spell,
 * then the quetzal map icon. Adapted from Ultimate Farming's FarmingInventoryOverlay.
 */
final class RumoursWidgetOverlay extends Overlay {
  /** The click to make now: items in blue, world targets in a lighter blue. */
  static final Color ITEM = new Color(0, 140, 255), TARGET = new Color(110, 200, 255);
  /** A click that's ready but not urgent, e.g. laying another trap. */
  static final Color NEXT = new Color(255, 150, 0);

  private static final int INVENTORY_TAB = 3, EQUIPMENT_TAB = 4, MAGIC_TAB = 6;
  private static final int[][] STONES = {
    {
      InterfaceID.Toplevel.STONE3,
      InterfaceID.ToplevelOsrsStretch.STONE3,
      InterfaceID.ToplevelPreEoc.STONE3
    },
    {
      InterfaceID.Toplevel.STONE4,
      InterfaceID.ToplevelOsrsStretch.STONE4,
      InterfaceID.ToplevelPreEoc.STONE4
    },
    {
      InterfaceID.Toplevel.STONE6,
      InterfaceID.ToplevelOsrsStretch.STONE6,
      InterfaceID.ToplevelPreEoc.STONE6
    }
  };
  /** Equipment slot index to its widget in the worn equipment tab. */
  private static final Map<Integer, Integer> WORN_SLOTS = new HashMap<>();

  static {
    int[] slots = {0, 1, 2, 3, 4, 5, 7, 9, 10, 12};
    int[] widgets = {
      InterfaceID.Wornitems.SLOT0,
      InterfaceID.Wornitems.SLOT1,
      InterfaceID.Wornitems.SLOT2,
      InterfaceID.Wornitems.SLOT3,
      InterfaceID.Wornitems.SLOT4,
      InterfaceID.Wornitems.SLOT5,
      InterfaceID.Wornitems.SLOT7,
      InterfaceID.Wornitems.SLOT9,
      InterfaceID.Wornitems.SLOT10,
      InterfaceID.Wornitems.SLOT12
    };
    for (int i = 0; i < slots.length; i++) WORN_SLOTS.put(slots[i], widgets[i]);
  }

  private static final Map<String, Integer> SPELLS = new HashMap<>();

  static {
    SPELLS.put("Civitas illa Fortis", InterfaceID.MagicSpellbook.FORTIS_TELEPORT);
    SPELLS.put("Teleport to House", InterfaceID.MagicSpellbook.TELEPORT_TO_YOUR_HOUSE);
    SPELLS.put("Ourania Teleport", InterfaceID.MagicSpellbook.OURANIA_TELEPORT);
    SPELLS.put("Telekinetic Grab", InterfaceID.MagicSpellbook.TELEGRAB);
  }

  private final RumoursPlugin plugin;
  private final RumoursConfig config;
  private final Client client;

  @Inject
  RumoursWidgetOverlay(RumoursPlugin plugin, RumoursConfig config, Client client) {
    this.plugin = plugin;
    this.config = config;
    this.client = client;
    setPosition(OverlayPosition.DYNAMIC);
    setLayer(OverlayLayer.ABOVE_WIDGETS);
  }

  @Override
  public Dimension render(Graphics2D g) {
    if (!config.highlight() || client.getGameState() != GameState.LOGGED_IN) return null;
    RumoursPlugin.View v = plugin.view();
    int open = client.getVarcIntValue(VarClientID.TOPLEVEL_PANEL);
    if (v.quetzalSite != null) markQuetzalDestination(g, v.quetzalSite);
    if (!v.bankItems.isEmpty()) markBank(g, v.bankItems);
    if (open == INVENTORY_TAB && !v.nextItems.isEmpty()) markInventory(g, v.nextItems, NEXT);
    if (!v.items.isEmpty() && !plugin.selectedItem(v.items)) {
      if (contains(InventoryID.INV, v.items)) {
        if (open != INVENTORY_TAB) mark(g, stone(0));
        else markInventory(g, v.items, ITEM);
        return null;
      }
      if (contains(InventoryID.WORN, v.items)) {
        if (open != EQUIPMENT_TAB) mark(g, stone(1));
        else {
          ItemContainer worn = client.getItemContainer(InventoryID.WORN);
          Item[] items = worn == null ? new Item[0] : worn.getItems();
          for (int i = 0; i < items.length; i++)
            if (v.items.contains(items[i].getId()) && WORN_SLOTS.containsKey(i))
              mark(g, client.getWidget(WORN_SLOTS.get(i)));
        }
        return null;
      }
    }
    // Once a spell is selected, only its target is left to click.
    if (v.spell != null && SPELLS.containsKey(v.spell) && !client.isWidgetSelected()) {
      if (open != MAGIC_TAB) mark(g, stone(2));
      else mark(g, client.getWidget(SPELLS.get(v.spell)));
    }
    return null;
  }

  private void markInventory(Graphics2D g, Set<Integer> ids, Color color) {
    Widget inventory = client.getWidget(InterfaceID.Inventory.ITEMS);
    Widget[] children =
        inventory == null || inventory.isHidden() ? null : inventory.getDynamicChildren();
    if (children == null) return;
    for (Widget item : children)
      if (item != null && !item.isHidden() && ids.contains(item.getItemId()))
        mark(g, item.getBounds(), color);
  }

  /** In the open bank, the missing items to withdraw (only those scrolled into view). */
  private void markBank(Graphics2D g, Set<Integer> ids) {
    Widget items = client.getWidget(InterfaceID.Bankmain.ITEMS);
    Widget container = client.getWidget(InterfaceID.Bankmain.ITEMS_CONTAINER);
    Widget[] children = items == null || items.isHidden() ? null : items.getDynamicChildren();
    if (children == null || container == null) return;
    Rectangle view = container.getBounds();
    for (Widget item : children)
      if (item != null
          && !item.isHidden()
          && ids.contains(item.getItemId())
          && view.contains(item.getBounds())) mark(g, item.getBounds(), ITEM);
  }

  /**
   * On the quetzal map (whistle or a quetzal NPC), highlights the landing site. UNVERIFIED: that the
   * icon's name or actions contain the site's words.
   */
  private void markQuetzalDestination(Graphics2D g, String site) {
    for (int id : new int[] {InterfaceID.QuetzalwhistleMenu.ICONS, InterfaceID.QuetzalMenu.ICONS}) {
      Widget icons = client.getWidget(id);
      if (icons == null || icons.isHidden()) continue;
      Widget[] children = icons.getDynamicChildren();
      if (children == null) continue;
      for (Widget icon : children) {
        if (icon == null || icon.isHidden()) continue;
        StringBuilder words = new StringBuilder(Text.removeTags(icon.getName()));
        if (icon.getActions() != null)
          for (String a : icon.getActions()) if (a != null) words.append(' ').append(a);
        if (words.toString().toLowerCase(Locale.ROOT).contains(site))
          mark(g, icon.getBounds(), ITEM);
      }
    }
  }

  private boolean contains(int container, Set<Integer> ids) {
    ItemContainer items = client.getItemContainer(container);
    if (items == null) return false;
    for (Item item : items.getItems()) if (ids.contains(item.getId())) return true;
    return false;
  }

  private Widget stone(int tab) {
    for (int id : STONES[tab]) {
      Widget w = client.getWidget(id);
      if (w != null && !w.isHidden()) return w;
    }
    return null;
  }

  static void mark(Graphics2D g, Widget w) {
    if (w == null || w.isHidden()) return;
    mark(g, w.getBounds(), ITEM);
  }

  /** Bright outline with a 20% fill. */
  static void mark(Graphics2D g, Shape shape, Color color) {
    if (shape == null) return;
    g.setColor(new Color(color.getRed(), color.getGreen(), color.getBlue(), 51));
    g.fill(shape);
    g.setColor(color);
    g.setStroke(new BasicStroke(2));
    g.draw(shape);
  }
}

package com.yonwi.rumours;

import java.awt.*;
import java.awt.event.MouseAdapter;
import java.awt.event.MouseEvent;
import javax.swing.*;
import javax.swing.border.EmptyBorder;
import javax.swing.plaf.basic.BasicComboBoxUI;
import javax.swing.plaf.basic.BasicComboPopup;
import javax.swing.plaf.basic.BasicScrollBarUI;
import javax.swing.plaf.basic.ComboPopup;
import net.runelite.client.ui.ColorScheme;
import net.runelite.client.ui.FontManager;

/**
 * Sidebar look shared by every tab: a green gradient header, bordered cards, gold accents, rounded
 * drop-downs and a slim scrollbar.
 *
 * <p>The header, card, drop-down and scrollbar styling is adapted from the Hunter Rumours plugin's
 * PreferredLocationPreferencesPanel (https://github.com/geel9/runelite-hunter-rumours),
 * BSD-2-Clause, Copyright (c) 2024, Joshua Coffey. See THIRD_PARTY_NOTICES.md.
 */
final class Style {
  static final Color BG = ColorScheme.DARK_GRAY_COLOR,
      CARD = ColorScheme.DARKER_GRAY_COLOR,
      CARD_BORDER = new Color(62, 63, 65),
      GOLD = new Color(214, 163, 62),
      INK = Color.WHITE,
      MUTED = new Color(170, 170, 170),
      HERO_TEXT = new Color(205, 215, 207),
      DONE = new Color(64, 82, 67),
      DONE_TEXT = new Color(150, 170, 154),
      SELECT_BACKGROUND = new Color(42, 44, 46),
      SELECT_BACKGROUND_HOVER = new Color(49, 52, 54),
      SELECT_BORDER = new Color(76, 79, 82),
      SELECT_BORDER_ACTIVE = new Color(170, 128, 49),
      SCROLL_TRACK = new Color(31, 32, 34),
      SCROLL_THUMB = new Color(91, 94, 97),
      SCROLL_THUMB_HOVER = new Color(118, 121, 124);

  private Style() {}

  /** A panel that stacks its children top to bottom, left-aligned. */
  static JPanel column() {
    JPanel p = new JPanel();
    p.setLayout(new BoxLayout(p, BoxLayout.Y_AXIS));
    p.setBackground(BG);
    p.setAlignmentX(Component.LEFT_ALIGNMENT);
    return p;
  }

  static Font bold() {
    return FontManager.getRunescapeBoldFont();
  }

  static Font small() {
    return FontManager.getRunescapeSmallFont();
  }

  /** Green gradient header with a capitalised title. */
  static JPanel hero(String title, JComponent subtitle) {
    JPanel hero =
        new JPanel() {
          @Override
          protected void paintComponent(Graphics graphics) {
            Graphics2D g = (Graphics2D) graphics.create();
            g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
            g.setPaint(
                new GradientPaint(
                    0, 0, new Color(50, 83, 58), getWidth(), getHeight(), new Color(35, 36, 38)));
            g.fillRoundRect(0, 0, getWidth(), getHeight(), 10, 10);
            g.dispose();
          }
        };
    hero.setOpaque(false);
    hero.setLayout(new BoxLayout(hero, BoxLayout.Y_AXIS));
    hero.setBorder(new EmptyBorder(13, 12, 12, 12));
    hero.setAlignmentX(Component.LEFT_ALIGNMENT);
    JLabel heading = new JLabel(title.toUpperCase());
    heading.setForeground(INK);
    heading.setFont(bold().deriveFont(Font.BOLD, 14f));
    // A little right padding: the bold font's last letter otherwise clips.
    heading.setBorder(new EmptyBorder(0, 0, 0, 4));
    heading.setAlignmentX(Component.LEFT_ALIGNMENT);
    hero.add(heading);
    if (subtitle != null) {
      subtitle.setForeground(HERO_TEXT);
      subtitle.setFont(small());
      subtitle.setBorder(new EmptyBorder(4, 0, 0, 0));
      subtitle.setAlignmentX(Component.LEFT_ALIGNMENT);
      hero.add(subtitle);
    }
    return hero;
  }

  /** A bordered card that lays its children out top to bottom. */
  static JPanel card() {
    JPanel card = column();
    card.setBackground(CARD);
    card.setBorder(
        BorderFactory.createCompoundBorder(
            BorderFactory.createLineBorder(CARD_BORDER), new EmptyBorder(9, 9, 9, 9)));
    return card;
  }

  /** Small gold section heading, like Hunter Rumours' "Search" label. */
  static JLabel section(String text) {
    JLabel l = new JLabel(text);
    l.setFont(small());
    l.setForeground(GOLD);
    l.setBorder(new EmptyBorder(6, 2, 3, 4));
    l.setAlignmentX(Component.LEFT_ALIGNMENT);
    return l;
  }

  static void combo(JComboBox<?> choice) {
    choice.setUI(new ComboUI());
    choice.setOpaque(false);
    choice.setBackground(SELECT_BACKGROUND);
    choice.setForeground(INK);
    choice.setFont(small());
    choice.setBorder(new EmptyBorder(1, 1, 1, 1));
    choice.setMaximumRowCount(8);
    choice.setPreferredSize(new Dimension(0, 30));
    ListCellRenderer<Object> base = new DefaultListCellRenderer();
    choice.setRenderer(
        (list, value, index, selected, focused) -> {
          JLabel label =
              (JLabel) base.getListCellRendererComponent(list, value, index, selected, focused);
          label.setOpaque(index >= 0);
          label.setFont(index < 0 ? bold() : small());
          label.setBorder(new EmptyBorder(index < 0 ? 5 : 7, 9, index < 0 ? 5 : 7, 7));
          label.setBackground(
              index < 0 ? new Color(0, 0, 0, 0) : selected ? DONE : SELECT_BACKGROUND);
          label.setForeground(selected && index >= 0 ? new Color(238, 218, 176) : INK);
          return label;
        });
  }

  static void scrollBar(JScrollBar bar) {
    bar.setPreferredSize(new Dimension(10, 0));
    bar.setUnitIncrement(48);
    bar.setBlockIncrement(240);
    bar.setUI(new ScrollUI());
  }

  private static final class ComboUI extends BasicComboBoxUI {
    private boolean hovered;

    @Override
    protected void installListeners() {
      super.installListeners();
      comboBox.addMouseListener(
          new MouseAdapter() {
            @Override
            public void mouseEntered(MouseEvent event) {
              hovered = true;
              comboBox.repaint();
            }

            @Override
            public void mouseExited(MouseEvent event) {
              hovered = false;
              comboBox.repaint();
            }
          });
    }

    @Override
    public void paint(Graphics graphics, JComponent component) {
      Graphics2D g = (Graphics2D) graphics.create();
      g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
      g.setColor(hovered ? SELECT_BACKGROUND_HOVER : SELECT_BACKGROUND);
      g.fillRoundRect(0, 0, component.getWidth() - 1, component.getHeight() - 1, 8, 8);
      g.setColor(
          comboBox.hasFocus() || comboBox.isPopupVisible() ? SELECT_BORDER_ACTIVE : SELECT_BORDER);
      g.drawRoundRect(0, 0, component.getWidth() - 1, component.getHeight() - 1, 8, 8);
      g.dispose();
      super.paint(graphics, component);
    }

    @Override
    public void paintCurrentValueBackground(Graphics graphics, Rectangle bounds, boolean focus) {
      // The rounded background is painted once in paint().
    }

    @Override
    protected JButton createArrowButton() {
      JButton button =
          new JButton() {
            @Override
            protected void paintComponent(Graphics graphics) {
              Graphics2D g = (Graphics2D) graphics.create();
              g.setRenderingHint(
                  RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
              g.setColor(getModel().isRollover() ? Color.WHITE : GOLD);
              int x = getWidth() / 2, y = getHeight() / 2;
              g.setStroke(new BasicStroke(1.8f, BasicStroke.CAP_ROUND, BasicStroke.JOIN_ROUND));
              g.drawLine(x - 4, y - 2, x, y + 2);
              g.drawLine(x, y + 2, x + 4, y - 2);
              g.dispose();
            }
          };
      button.setOpaque(false);
      button.setContentAreaFilled(false);
      button.setBorderPainted(false);
      button.setFocusPainted(false);
      button.setRolloverEnabled(true);
      button.setCursor(Cursor.getPredefinedCursor(Cursor.HAND_CURSOR));
      return button;
    }

    @Override
    protected ComboPopup createPopup() {
      return new BasicComboPopup(comboBox) {
        @Override
        protected void configurePopup() {
          super.configurePopup();
          setBorder(BorderFactory.createLineBorder(SELECT_BORDER_ACTIVE));
        }

        @Override
        protected void configureList() {
          super.configureList();
          list.setBackground(SELECT_BACKGROUND);
          list.setSelectionBackground(DONE);
          list.setSelectionForeground(Color.WHITE);
          list.setFixedCellHeight(30);
        }

        @Override
        protected JScrollPane createScroller() {
          JScrollPane scroller = super.createScroller();
          scroller.setBorder(BorderFactory.createEmptyBorder());
          scroller.getVerticalScrollBar().setPreferredSize(new Dimension(8, 0));
          scroller.getVerticalScrollBar().setUnitIncrement(30);
          scroller.getVerticalScrollBar().setUI(new ScrollUI());
          return scroller;
        }
      };
    }
  }

  private static final class ScrollUI extends BasicScrollBarUI {
    @Override
    protected void configureScrollBarColors() {
      trackColor = SCROLL_TRACK;
      thumbColor = SCROLL_THUMB;
      thumbDarkShadowColor = SCROLL_THUMB;
      thumbHighlightColor = SCROLL_THUMB;
      thumbLightShadowColor = SCROLL_THUMB;
    }

    @Override
    protected JButton createDecreaseButton(int orientation) {
      return zeroButton();
    }

    @Override
    protected JButton createIncreaseButton(int orientation) {
      return zeroButton();
    }

    @Override
    protected void paintTrack(Graphics graphics, JComponent component, Rectangle bounds) {
      graphics.setColor(SCROLL_TRACK);
      graphics.fillRect(bounds.x, bounds.y, bounds.width, bounds.height);
    }

    @Override
    protected void paintThumb(Graphics graphics, JComponent component, Rectangle bounds) {
      if (bounds.isEmpty() || !scrollbar.isEnabled()) return;
      Graphics2D g = (Graphics2D) graphics.create();
      g.setRenderingHint(RenderingHints.KEY_ANTIALIASING, RenderingHints.VALUE_ANTIALIAS_ON);
      g.setColor(isThumbRollover() ? SCROLL_THUMB_HOVER : SCROLL_THUMB);
      g.fillRoundRect(
          bounds.x + 2,
          bounds.y + 2,
          Math.max(4, bounds.width - 4),
          Math.max(8, bounds.height - 4),
          6,
          6);
      g.dispose();
    }

    private static JButton zeroButton() {
      JButton button = new JButton();
      Dimension zero = new Dimension(0, 0);
      button.setPreferredSize(zero);
      button.setMinimumSize(zero);
      button.setMaximumSize(zero);
      return button;
    }
  }
}

package com.yonwi.rumours;

import net.runelite.api.gameval.ItemID;

/**
 * How each rumour creature is caught, and its pity threshold without and with the full guild
 * hunter outfit.
 *
 * <p>Names and thresholds are from the Hunter Rumours plugin's Trap enum
 * (https://github.com/geel9/runelite-hunter-rumours), BSD-2-Clause, Copyright (c) 2024, Joshua
 * Coffey. Item IDs were re-looked-up in the gameval ItemID table. See THIRD_PARTY_NOTICES.md.
 */
enum Trap {
  SNARE("Bird snare", true, 40, 38, ItemID.HUNTING_OJIBWAY_BIRD_SNARE),
  DEADFALL("Deadfall", false, 30, 28, ItemID.LOGS),
  NET_TRAP("Net trap", false, 50, 46, Kit.NET_TRAP, ItemID.NET, ItemID.ROPE),
  PIT("Pit trap", false, 30, 28, ItemID.HUNTING_TEASING_STICK),
  GOAT_PIT("Goat pit", false, 96, 90, ItemID.CATTLEPROD),
  BOX_TRAP("Box trap", true, 100, 94, ItemID.HUNTING_BOX_TRAP),
  FALCONRY("Falconry", false, 20, 18, ItemID.FALCON_GLOVES),
  BUTTERFLY("Butterfly net", false, 80, 76, ItemID.HUNTING_BUTTERFLY_NET, ItemID.II_MAGIC_BUTTERFLY_NET),
  NOOSE("Tracking", false, 30, 28, ItemID.NOOSE_WAND),
  NOOSE_HERBIBOAR("Tracking", false, 14, 12, ItemID.NOOSE_WAND);

  final String name;
  /** Laid from the inventory ("Lay"), so the trap item itself is the next click. */
  final boolean laidFromInventory;

  final int pity, pityWithOutfit;
  /** The tool or trap item; any one of them will do. */
  final int[] items;

  Trap(String name, boolean laidFromInventory, int pity, int pityWithOutfit, int... items) {
    this.name = name;
    this.laidFromInventory = laidFromInventory;
    this.pity = pity;
    this.pityWithOutfit = pityWithOutfit;
    this.items = items;
  }

  /** Each worn outfit piece takes a quarter of the full outfit's reduction off, rounded down. */
  int pityFor(int outfitPieces) {
    return (int) Math.floor(pity - (pity - pityWithOutfit) / 4d * outfitPieces);
  }
}

package com.yonwi.rumours;

import java.util.*;
import net.runelite.api.Quest;
import net.runelite.api.coords.WorldPoint;
import net.runelite.api.gameval.ItemID;

/**
 * Ways to reach a rumour area or the Hunter Guild, and the choice of the quickest one the player
 * can use. Like Ultimate Farming's route choices: each area lists its options with a rough cost,
 * each option needs unlocks (quests, diaries, spellbook) and items, and the cheapest one the
 * player has unlocked and owns (carried, banked or in the huntsman's kit) is picked.
 *
 * <p>Sources: OSRS wiki pages "Fairy ring" (AJP is in the Avium Savannah; a dramen or lunar staff
 * is needed unless the Lumbridge &amp; Draynor elite diary is done), "Ourania Hunter area" (Ourania
 * Teleport, spirit tree to the Battlefield, Ardougne cloak to the Monastery), "Wyrmscraig" (necklace
 * of passage, slayer ring, Ardeaglais teleport; Fallen From Grace), and the Hunter Rumours plugin's
 * fairy ring codes. UNVERIFIED (from memory): the guild's surface position, which areas are a walk
 * from the guild, the quetzal map icon wording, the digsite pendant's Fossil Island option, and
 * the fairy ring being named "Fairy ring".
 */
final class Travel {
  /** Burrows bounds from the Hunter Rumours plugin's isInBurrows (BSD-2, Joshua Coffey). */
  static boolean inBurrows(WorldPoint p) {
    return p != null
        && p.getPlane() == 0
        && p.getX() >= 1549
        && p.getX() <= 1565
        && p.getY() >= 9449
        && p.getY() <= 9464;
  }

  /** UNVERIFIED: the burrows sit under the guild, so its surface is the burrows minus 6400 in y. */
  static final WorldPoint GUILD = new WorldPoint(1557, 3049, 0);

  /** The underground area around the burrows, which holds the guild's moonlight creatures. */
  static boolean underGuild(WorldPoint p) {
    return p != null && p.getY() > 9300 && p.getY() < 9500 && p.getX() > 1500 && p.getX() < 1620;
  }

  static boolean nearGuild(WorldPoint p) {
    return p != null && p.distanceTo(GUILD) <= 40;
  }

  static final int[] WHISTLES = com.yonwi.rumours.Kit.IDS.get("Quetzal whistle");
  static final int[] FORTIS_TABLET = com.yonwi.rumours.Kit.IDS.get("Civitas illa Fortis teleport");

  /** What the player has and has unlocked. Called on the client thread. */
  interface Kit {
    /** Carried or worn now. */
    boolean carries(int[] ids);

    /** Carried, worn, last seen in the bank, or in the huntsman's kit. */
    boolean owns(int[] ids);

    /** 0 standard, 1 ancient, 2 lunar, 3 arceuus. */
    int spellbook();

    boolean finished(Quest quest);

    boolean started(Quest quest);

    /** Lumbridge &amp; Draynor elite diary: fairy rings work without a staff. */
    boolean staffless();

    /** A house teleport: tablet or construction cape, or the spell with its runes. */
    boolean house(boolean carriedOnly);

    /** From the plugin's "Your house" settings. */
    boolean pohFairy();

    boolean pohSpirit();

    boolean pohNexus();

    /** Any jewellery box (all have the ring of dueling). */
    boolean pohJewellery();

    /** Jewellery box tier: 0 none, 1 basic, 2 fancy, 3 ornate. */
    default int pohJewelleryTier() {
      return pohJewellery() ? 3 : 0;
    }
  }

  /** One way to travel: say it, then highlight its item, spell, map icon or world object. */
  static final class Route {
    final String text;
    /** Items to click to use the route (highlighted in the inventory or worn tab). */
    int[] items = new int[0];
    /** Spell to cast from the spellbook, or null. */
    String spell;
    /** Lower-case words the quetzal map icon should contain, or null. */
    String quetzalSite;
    /** A second leg (e.g. a quetzal ride or a fairy ring) follows the first click. */
    boolean multiLeg;
    /** A world object to click, by name (e.g. "Fairy ring"), or null. */
    String object;
    /** Items the route needs: shown in the kit and the bank filter. */
    final List<String> needs = new ArrayList<>();
    /** Rough cost; lower is quicker. */
    double cost;
    /** Starts with a house teleport; then {@link #pohObject} is used inside the house. */
    boolean house;
    /** Lower-case word naming the house object to use (fairy, spirit, nexus, jewellery). */
    String pohObject;
    /** What to pick on it, e.g. "A K Q" or "Ourania Cave". */
    String pohChoice;

    Route(String text, double cost) {
      this.text = text;
      this.cost = cost;
    }

    Route items(String group) {
      needs.add(group);
      items = Kit_.ids(group);
      return this;
    }

    Route need(String group) {
      needs.add(group);
      return this;
    }

    /** House teleport, then this object in the house and this choice on it. */
    Route viaHouse(String object, String choice) {
      house = true;
      pohObject = object;
      pohChoice = choice;
      multiLeg = true;
      needs.add(com.yonwi.rumours.Kit.HOUSE_TELEPORT);
      return this;
    }

    boolean usable(Travel.Kit kit) {
      for (String n : needs)
        if (n.equals(com.yonwi.rumours.Kit.HOUSE_TELEPORT) ? !kit.house(false) : !kit.owns(Kit_.ids(n)))
          return false;
      return true;
    }

    boolean carried(Travel.Kit kit) {
      for (String n : needs)
        if (n.equals(com.yonwi.rumours.Kit.HOUSE_TELEPORT) ? !kit.house(true) : !kit.carries(Kit_.ids(n)))
          return false;
      return true;
    }

    @Override
    public String toString() {
      return text;
    }
  }

  /** Shorthand for the item table, which lives in {@link com.yonwi.rumours.Kit}. */
  private static final class Kit_ {
    static int[] ids(String group) {
      return com.yonwi.rumours.Kit.IDS.getOrDefault(group, new int[0]);
    }
  }

  static final Route WALK = new Route("Walk", 0);

  /** Routes that land at (or fly on to) a quetzal site. */
  static List<Route> viaQuetzal(String site, String siteWords, double cost) {
    List<Route> out = new ArrayList<>();
    Route whistle = new Route("Quetzal whistle → " + site, cost).items("Quetzal whistle");
    whistle.quetzalSite = siteWords;
    out.add(whistle);
    Route tablet =
        new Route("Civitas illa Fortis teleport → quetzal to " + site, cost + 8)
            .items("Civitas illa Fortis teleport");
    tablet.quetzalSite = siteWords;
    tablet.multiLeg = true;
    out.add(tablet);
    // Spell routes need runes; every teleport spell takes a law rune (rune pouch). UNVERIFIED: the
    // rest of the rune cost isn't checked.
    Route spell = new Route("Civitas illa Fortis teleport (spell) → quetzal to " + site, cost + 8).need("Law rune");
    spell.spell = "Civitas illa Fortis";
    spell.quetzalSite = siteWords;
    spell.multiLeg = true;
    out.add(spell);
    return out;
  }

  /** The cheapest usable route, preferring one whose items are already carried. */
  static Route best(List<Route> routes, Kit kit) {
    Route best = null;
    double bestCost = Double.MAX_VALUE;
    for (Route r : routes) {
      if (r.spell != null && r.spell.startsWith("Civitas") && kit.spellbook() != 0) continue;
      if (!r.usable(kit)) continue;
      double c = r.cost + (r.carried(kit) ? 0 : 2);
      if (c < bestCost) {
        best = r;
        bestCost = c;
      }
    }
    return best;
  }

  /** The way back to the burrows from wherever the player is. */
  static Route toGuild(WorldPoint here, Kit kit) {
    if (underGuild(here) || here.distanceTo(GUILD) <= 120) return WALK;
    Route r = best(guildOptions(kit), kit);
    return r != null ? r : new Route("Make your way to the Hunter Guild", 1000);
  }

  /** Every way back to the guild from far away. */
  static List<Route> guildOptions(Kit kit) {
    List<Route> all = new ArrayList<>(viaQuetzal("Hunter Guild", "hunter guild", 10));
    // From the house (wiki: fairy ring AJP is in the Avium Savannah; the nexus has Civitas illa
    // Fortis; every jewellery box has the ring of dueling's Fortis Colosseum).
    if (kit.pohFairy())
      all.add(new Route("House teleport → fairy ring A J P, then walk to the guild", 14).viaHouse("fairy", "A J P"));
    if (kit.pohNexus())
      all.add(new Route("House teleport → nexus: Civitas illa Fortis → quetzal to Hunter Guild", 16).viaHouse("nexus", "Civitas illa Fortis"));
    if (kit.pohJewellery())
      all.add(new Route("House teleport → jewellery box: Fortis Colosseum → quetzal to Hunter Guild", 17).viaHouse("jewellery", "Fortis Colosseum"));
    return all;
  }

  /**
   * The quickest way to a bank from far away, using only what's owned. Wiki "Ornate jewellery
   * box": the basic box has the ring of dueling (Ferox Enclave), the fancy one adds the skills
   * necklace (Crafting Guild), the ornate one the ring of wealth (Grand Exchange). UNVERIFIED: how
   * far each landing spot is from its bank.
   */
  static List<Route> bankOptions(Kit kit) {
    List<Route> all = new ArrayList<>();
    all.add(new Route("Crafting cape → Crafting Guild bank", 5).items("Crafting cape"));
    all.add(new Route("Ring of dueling → Ferox Enclave bank", 6).items("Ring of dueling"));
    int box = kit.pohJewelleryTier();
    if (box >= 1)
      all.add(new Route("House teleport → jewellery box: Ferox Enclave bank", 9).viaHouse("jewellery", "Ferox Enclave"));
    if (box >= 2)
      all.add(new Route("House teleport → jewellery box: Crafting Guild bank", 10).viaHouse("jewellery", "Crafting Guild"));
    if (box >= 3)
      all.add(new Route("House teleport → jewellery box: Grand Exchange", 11).viaHouse("jewellery", "Grand Exchange"));
    Route w = new Route("Quetzal whistle → Hunter Guild, then the burrows bank", 12).items("Quetzal whistle");
    w.quetzalSite = "hunter guild";
    all.add(w);
    return all;
  }

  /** Away from a bank the route's item has to be on you already. */
  static Route toBank(Kit kit) {
    List<Route> carried = new ArrayList<>();
    for (Route r : bankOptions(kit)) if (r.carried(kit)) carried.add(r);
    Route r = best(carried, kit);
    return r != null ? r : new Route("Make your way to a bank", 1000);
  }

  /** The burrows, where every trip starts. */
  static final WorldPoint BURROWS = new WorldPoint(1557, 9456, 0);

  /**
   * One set of travel items for every rumour the hunter gives, and the way back: the smallest
   * set first, then the quickest routes. Each new item group costs as much as 15 points of route
   * cost, so a route that reuses the loadout's items (e.g. one house teleport for the house fairy
   * ring and the nexus) beats a slightly quicker one that needs another item.
   */
  static final class Loadout {
    final Map<Rumour, Plan> plans = new LinkedHashMap<>();
    Route back;
    /** Item groups (Kit.IDS names, plus Kit.HOUSE_TELEPORT) the loadout carries. */
    final Set<String> groups = new LinkedHashSet<>();
  }

  private static final double ITEM_WEIGHT = 15;

  static Loadout loadout(List<Rumour> pool, Kit kit) {
    Map<Rumour, List<Plan>> choices = new LinkedHashMap<>();
    for (Rumour r : pool) {
      List<Plan> list = new ArrayList<>();
      Map<String, List<RumourLocation>> areas = new LinkedHashMap<>();
      for (RumourLocation l : RumourLocation.values())
        if (l.getRumour() == r) areas.computeIfAbsent(l.getLocationName(), k -> new ArrayList<>()).add(l);
      for (Map.Entry<String, List<RumourLocation>> e : areas.entrySet()) {
        List<WorldPoint> points = new ArrayList<>();
        for (RumourLocation l : e.getValue()) points.add(l.getWorldPoint());
        String ring = e.getValue().get(0).getFairyRingCode();
        if (GUILD_AREAS.contains(e.getKey())) {
          list.add(new Plan(e.getKey(), ring, points, WALK, Collections.emptyList(), 4));
          continue;
        }
        for (Route route : options(e.getKey(), ring, BURROWS, kit))
          if (route.usable(kit) && !(route.spell != null && route.spell.startsWith("Civitas") && kit.spellbook() != 0))
            list.add(new Plan(e.getKey(), ring, points, route, Collections.emptyList(), route.cost));
      }
      if (!list.isEmpty()) choices.put(r, list);
    }
    List<Route> back = new ArrayList<>();
    for (Route route : guildOptions(kit))
      if (route.usable(kit) && !(route.spell != null && route.spell.startsWith("Civitas") && kit.spellbook() != 0))
        back.add(route);

    Map<Rumour, Plan> chosen = new LinkedHashMap<>();
    Route chosenBack = null;
    // Two passes: the second revisits each choice knowing what the others carry.
    for (int pass = 0; pass < 2; pass++) {
      List<Rumour> order = new ArrayList<>(choices.keySet());
      order.sort(Comparator.comparingInt(r -> choices.get(r).size()));
      for (Rumour r : order) {
        Set<String> others = groupsExcept(chosen, chosenBack, r, false);
        Plan best = null;
        double bestScore = Double.MAX_VALUE;
        for (Plan p : choices.get(r)) {
          double s = p.cost + ITEM_WEIGHT * newGroups(p.route, others);
          if (s < bestScore) {
            best = p;
            bestScore = s;
          }
        }
        chosen.put(r, best);
      }
      Set<String> others = groupsExcept(chosen, null, null, true);
      double bestScore = Double.MAX_VALUE;
      for (Route route : back) {
        double s = route.cost + ITEM_WEIGHT * newGroups(route, others);
        if (s < bestScore) {
          chosenBack = route;
          bestScore = s;
        }
      }
    }
    Loadout l = new Loadout();
    l.plans.putAll(chosen);
    l.back = chosenBack;
    for (Plan p : chosen.values()) l.groups.addAll(p.route.needs);
    if (chosenBack != null) l.groups.addAll(chosenBack.needs);
    return l;
  }

  private static Set<String> groupsExcept(Map<Rumour, Plan> chosen, Route back, Rumour skip, boolean skipBack) {
    Set<String> out = new HashSet<>();
    for (Map.Entry<Rumour, Plan> e : chosen.entrySet()) if (e.getKey() != skip) out.addAll(e.getValue().route.needs);
    if (!skipBack && back != null) out.addAll(back.needs);
    return out;
  }

  private static int newGroups(Route r, Set<String> have) {
    int n = 0;
    for (String g : r.needs) if (!have.contains(g)) n++;
    return n;
  }

  /**
   * Like {@link #plan(Rumour, WorldPoint, Kit)}, but uses the loadout's area and route for the
   * rumour whenever a teleport is needed, so the guide never asks for anything outside it.
   */
  static Plan plan(Rumour rumour, WorldPoint here, Kit kit, Loadout loadout) {
    Plan normal = plan(rumour, here, kit);
    Plan chosen = loadout == null ? null : loadout.plans.get(rumour);
    if (chosen == null || normal == null || normal.route == WALK && normal.distance(here) <= 100)
      return normal;
    if (chosen.route == WALK) return candidate(chosen.area, chosen.fairyRing, chosen.points, here, kit);
    if (!chosen.route.usable(kit)) return normal;
    List<Route> others = new ArrayList<>();
    for (Route r : options(chosen.area, chosen.fairyRing, here, kit))
      if (!r.text.equals(chosen.route.text) && r.usable(kit)) others.add(r);
    // The fairy ring next to the guild only makes sense from the guild.
    Route route = chosen.route;
    if (route.object != null && !(underGuild(here) || nearGuild(here)))
      for (Route r : options(chosen.area, chosen.fairyRing, here, kit))
        if (r.object != null && !r.house) route = r;
    return new Plan(chosen.area, chosen.fairyRing, chosen.points, route, others, route.cost);
  }

  /** A rumour area (one named group of RumourLocation points) and the way there. */
  static final class Plan {
    final String area;
    final String fairyRing;
    final List<WorldPoint> points;
    final Route route;
    /** Other usable ways to the same area, quickest first. */
    final List<Route> alternatives;
    final double cost;

    Plan(String area, String fairyRing, List<WorldPoint> points, Route route, List<Route> alternatives, double cost) {
      this.area = area;
      this.fairyRing = fairyRing;
      this.points = points;
      this.route = route;
      this.alternatives = alternatives;
      this.cost = cost;
    }

    int distance(WorldPoint p) {
      int best = Integer.MAX_VALUE;
      for (WorldPoint w : points) best = Math.min(best, w.distanceTo(p));
      return best;
    }
  }

  /** UNVERIFIED: areas a short run from the Hunter Guild landing site or its stairs. */
  private static final Set<String> GUILD_AREAS =
      new HashSet<>(
          Arrays.asList(
              "Avium Savannah",
              "West of Hunter Guild",
              "Ralos' Rise",
              "Hunters' Guild",
              "North-west of the Locus Oasis"));

  /** UNVERIFIED: other areas with a quetzal landing site of their own. */
  private static final Map<String, String[]> QUETZAL_AREAS = new HashMap<>();

  static {
    QUETZAL_AREAS.put(
        "Tlati Rainforest (NE of Tal Teklan quetzal)", new String[] {"Tal Teklan", "tal teklan"});
    QUETZAL_AREAS.put("Auburnvale", new String[] {"Auburnvale", "auburn"});
  }

  /** Every way to reach an area, before checking what the player has. */
  static List<Route> options(String area, String ring, WorldPoint here, Kit kit) {
    List<Route> out = new ArrayList<>();
    if (GUILD_AREAS.contains(area)) out.addAll(viaQuetzal("Hunter Guild", "hunter guild", 10));
    String[] site = QUETZAL_AREAS.get(area);
    if (site != null) out.addAll(viaQuetzal(site[0], site[1], 12));
    switch (area) {
      case "Ourania Hunter area":
        if (kit.spellbook() == 2 && kit.finished(Quest.LUNAR_DIPLOMACY)) {
          Route r = new Route("Ourania Teleport (Lunar) → straight to the salamanders", 6).need("Law rune");
          r.spell = "Ourania Teleport";
          out.add(r);
        }
        if (kit.pohNexus())
          out.add(new Route("House teleport → nexus: Ourania Cave → the salamanders", 9).viaHouse("nexus", "Ourania Cave"));
        if (kit.pohSpirit() && kit.finished(Quest.TREE_GNOME_VILLAGE))
          out.add(new Route("House teleport → spirit tree: Battlefield, then walk west", 16).viaHouse("spirit", "Battlefield"));
        out.add(
            new Route("Ardougne cloak → Monastery, then walk west", 14).items("Ardougne cloak"));
        // A spirit tree is only reachable here through the house (none near the guild).
        break;
      case "Mushroom Forest on Fossil Island":
        if (kit.finished(Quest.BONE_VOYAGE)) {
          Route r =
              new Route("Digsite pendant → Fossil Island, then north to the Mushroom Forest", 12)
                  .items("Digsite pendant");
          out.add(r);
        }
        break;
      case "Wyrmscraig (Necklace of Passage)":
        if (kit.finished(Quest.FALLEN_FROM_GRACE)) {
          out.add(new Route("Necklace of passage → Wyrmscraig, then south", 8).items("Necklace of passage"));
          out.add(new Route("Ardeaglais teleport → Wyrmscraig, then south", 8.5).items("Ardeaglais teleport"));
          out.add(new Route("Slayer ring → Wyrmscraig, then south", 9).items("Slayer ring"));
        }
        break;
      default:
    }
    if (ring != null && ring.length() == 3 && kit.started(Quest.FAIRYTALE_II__CURE_A_QUEEN)) {
      String code = ring.charAt(0) + " " + ring.charAt(1) + " " + ring.charAt(2);
      boolean local = underGuild(here) || nearGuild(here);
      Route r =
          new Route(
              (local ? "Fairy ring AJP (Avium Savannah) → " : "Fairy ring → ") + code, local ? 20 : 25);
      r.object = "Fairy ring";
      r.multiLeg = true;
      if (!kit.staffless()) r.need("Dramen or lunar staff");
      out.add(r);
      if (kit.pohFairy()) {
        Route h = new Route("House teleport → fairy ring " + code, 15).viaHouse("fairy", code);
        if (!kit.staffless()) h.need("Dramen or lunar staff");
        out.add(h);
      }
    }
    return out;
  }

  /** Picks the rumour area that's quickest to reach, how to get there, and the alternatives. */
  static Plan plan(Rumour rumour, WorldPoint here, Kit kit) {
    Map<String, List<RumourLocation>> areas = new LinkedHashMap<>();
    for (RumourLocation l : RumourLocation.values())
      if (l.getRumour() == rumour)
        areas.computeIfAbsent(l.getLocationName(), k -> new ArrayList<>()).add(l);
    Plan best = null;
    for (Map.Entry<String, List<RumourLocation>> e : areas.entrySet()) {
      List<WorldPoint> points = new ArrayList<>();
      for (RumourLocation l : e.getValue()) points.add(l.getWorldPoint());
      String ring = e.getValue().get(0).getFairyRingCode();
      Plan p = candidate(e.getKey(), ring, points, here, kit);
      if (best == null || p.cost < best.cost) best = p;
    }
    return best;
  }

  private static Plan candidate(
      String area, String ring, List<WorldPoint> points, WorldPoint here, Kit kit) {
    Plan probe = new Plan(area, ring, points, WALK, Collections.emptyList(), 0);
    int fromHere = probe.distance(here);
    boolean guildArea = GUILD_AREAS.contains(area);
    // Already close, or setting off from the guild to one of its own areas: no teleport.
    if (fromHere <= 100 || guildArea && (underGuild(here) || nearGuild(here)))
      return new Plan(area, ring, points, WALK, Collections.emptyList(), fromHere <= 100 ? fromHere / 10.0 : 4);
    List<Route> all = options(area, ring, here, kit);
    Route route = best(all, kit);
    List<Route> others = new ArrayList<>();
    for (Route r : all) if (r != route && r.usable(kit) && !(r.spell != null && r.spell.startsWith("Civitas") && kit.spellbook() != 0)) others.add(r);
    others.sort(Comparator.comparingDouble(r -> r.cost));
    if (route == null)
      return new Plan(area, ring, points, new Route("Make your way to " + area, 1000), others, 1000);
    return new Plan(area, ring, points, route, others, route.cost);
  }

  private Travel() {}
}

package com.yonwi.rumours;

import net.runelite.client.RuneLite;
import net.runelite.client.externalplugins.ExternalPluginManager;

public class EasyRumoursPluginTest {
  public static void main(String[] args) throws Exception {
    ExternalPluginManager.loadBuiltin(RumoursPlugin.class);
    RuneLite.main(args);
  }
}

package com.yonwi.rumours;

import static org.junit.Assert.*;

import org.junit.Test;

public class RumourDataTest {
  @Test
  public void pityDropsAQuarterOfTheOutfitReductionPerPiece() {
    // One outfit piece, sunlight moth (butterfly net) -> 79.
    assertEquals(79, Trap.BUTTERFLY.pityFor(1));
    assertEquals(80, Trap.BUTTERFLY.pityFor(0));
    assertEquals(76, Trap.BUTTERFLY.pityFor(4));
  }

  @Test
  public void parsesRumourAndHunterFromText() {
    assertEquals(Rumour.SUNLIGHT_MOTH, Rumour.mentionedIn("I've heard of a sunlight moth nearby."));
    assertEquals(Rumour.NONE, Rumour.mentionedIn("Nothing to see here."));
    assertEquals(Hunter.TECO, Hunter.mentionedIn("Teco has one for you"));
    // "Aco" must not match inside other words.
    assertEquals(Hunter.NONE, Hunter.mentionedIn("tobacco and macaroni"));
  }

  @Test
  public void everyKitItemHasIds() {
    for (java.util.List<Rumour> pool : Kit.POOLS.values())
      for (Rumour r : pool)
        for (Kit.Need need : Kit.needs(r, 80))
          assertTrue(need.item, need.ids().length > 0 || need.item.equals(Kit.TELEGRAB));
    assertEquals(7, Kit.POOLS.get(Hunter.TECO).size());
    assertEquals(5, Kit.trapCount(80));
  }

  @Test
  public void everyRumourHasAnArea() {
    for (Rumour r : Rumour.values()) {
      if (r == Rumour.NONE || r == Rumour.RAZOR_BACKED_KEBBIT) continue;
      boolean found = false;
      for (RumourLocation l : RumourLocation.values()) found |= l.getRumour() == r;
      assertTrue(r.name(), found);
    }
  }
}

package com.yonwi.rumours;

import static org.junit.Assert.*;

import java.util.*;
import net.runelite.api.Quest;
import net.runelite.api.coords.WorldPoint;
import org.junit.Test;

public class TravelTest {
  private static final WorldPoint BURROWS = new WorldPoint(1557, 9456, 0);

  /** A test account: owns the named item groups, has finished every quest, standard spellbook. */
  private static boolean house;

  private static Travel.Kit owning(boolean staffless, String... groups) {
    Set<Integer> owned = new HashSet<>();
    for (String g : groups) for (int id : Kit.IDS.get(g)) owned.add(id);
    return new Travel.Kit() {
      public boolean carries(int[] ids) {
        return false;
      }

      public boolean owns(int[] ids) {
        for (int id : ids) if (owned.contains(id)) return true;
        return false;
      }

      public int spellbook() {
        return 0;
      }

      public boolean finished(Quest q) {
        return true;
